def shortest_path(edges, start, end):
    """
    Find the shortest path from start to end in a directed weighted graph.

    Args:
        edges: List of tuples (from_node, to_node, weight) representing one-way streets.
        start: Starting node.
        end: Ending node.

    Returns:
        A tuple (distance, path) where:
            - distance is the total shortest distance, or None if no path exists
            - path is a list of nodes from start to end, or None if no path exists

        Special cases:
            - If start == end, returns (0, [start])
            - If any edge has negative weight, raises ValueError
            - If no route exists, returns (None, None)
    """
    # Check for negative weights
    for _, _, weight in edges:
        if weight < 0:
            raise ValueError("Edge weights cannot be negative")

    # If start and end are the same, return zero distance and path with just start
    if start == end:
        return (0, [start])

    # Build adjacency list and collect all nodes
    from collections import defaultdict
    import heapq

    graph = defaultdict(list)
    all_nodes = set()
    for from_node, to_node, weight in edges:
        graph[from_node].append((to_node, weight))
        all_nodes.add(from_node)
        all_nodes.add(to_node)

    # Check if start or end are in the graph
    # start should be in all_nodes if there are edges, but if edges is empty, handle accordingly

    if start not in all_nodes and end not in all_nodes:
        # No edges at all, and start != end, so no path
        return (None, None)

    if start not in all_nodes:
        return (None, None)

    if end not in all_nodes:
        return (None, None)

    # Dijkstra's algorithm
    INF = float('inf')
    dist = {node: INF for node in all_nodes}
    prev = {node: None for node in all_nodes}
    dist[start] = 0

    heap = [(0, start)]

    while heap:
        d, u = heapq.heappop(heap)

        # Skip if we've already found a shorter path to u
        if d > dist[u]:
            continue

        if u == end:
            break

        for v, weight in graph[u]:
            new_dist = dist[u] + weight
            if new_dist < dist[v]:
                dist[v] = new_dist
                prev[v] = u
                heapq.heappush(heap, (new_dist, v))

    # Check if end was reachable
    if dist[end] == INF:
        return (None, None)

    # Reconstruct path
    path = []
    current = end
    while current is not None:
        path.append(current)
        current = prev[current]

    path.reverse()

    return (dist[end], path)
